/* ════════════════════════════════════════════════════════════════════════
   17.0: КНИГА РЕМЕСЛЕННЫХ ДЕЛ — СТО ТРИНАДЦАТЬ ДЕЛ ПО РЕМЁСЛАМ И ТРИ ДЕРЖАВНЫЕ ЦЕПИ
   Просьба игрока: «Добавь по этому принципу кучу различных социальных квестов… квесты абсолютно разнообразные…
   чтобы игрок изучал мир по этим квестам». Мастер-промпт: библиотека дел по ремёслам (кузнецы, кожевенники,
   стражники, трактирщики, жители, торговцы и прочие), долгие державные цепи с последствиями, что приходят позже.
   Всё — через тот же движок больших дел (Цепи170): те же шаги, метки, маяк, список заданий, награды, отношение
   и слава ремесла. Ничего отдельного: у жителя в «Заданиях» в день — одно большое дело и два малых.
   1. Дела ремёсел (малые, на час-другой): кузнецы — 15, кожевенные мастера — 12, стража — 15, трактирщики — 15,
      жители деревень — 20 (крестьяне, старосты, целительницы), торговый люд — 20, прочие — 16 (жрецы, лекари,
      маги, странники, советники, кланы). Виды: принести, отнести груз в другое поселение, передать весть,
      привезти оттуда, охота в округе, засада, найти на карте, починить, сбор из нескольких дел; у многих —
      решение с последствиями; у иных — срок (не успели — дело провалено, заказчик запомнит).
   2. Державные цепи (на день и больше): «Дорога трёх земель» — подорожная через три земли, пошлины, война
      соседей, договор, который отзовётся через несколько дней; «Великая засуха» — река, соседи, колодцы, обряд;
      «Мятежный наместник» — переписка, наёмники, выбор между короной, сделкой и мятежом.
   3. Отложенные последствия: иные решения отзываются через дни — вестью и переменой отношения.
   ════════════════════════════════════════════════════════════════════════ */
const Дела170={
 опись(что){return Object.entries(что||{}).map(([a,b])=>`${a} ×${b}`).join(", ");},
 ур(){return Math.max(1,Number(G.level)||1);},
 награда(r,x){const т=Math.max(1,Math.min(3,r.ур||1));const L=this.ур();const н={золото:[0,30+5*L,60+8*L,110+12*L][т],опыт:[0,80,160,260][т]};
  if(т>=2&&x.h("з")<0.5)н.зелья=[{r:т-1}];if(т>=3&&x.h("зд")<0.25)н.зелья=(н.зелья||[]).concat([{r:2,двойное:true}]);
  const отн=[];if(x.дом.ключ&&/^Деревня /.test(x.дом.ключ))отн.push(["vill",x.дом.ключ,2+т]);if(r.отношение)отн.push(...r.отношение);н.отношение=отн;
  if(r.сырьё)н.сырьё=r.сырьё;if(r.вещь)н.вещь=r.вещь;return н;},
 /* один шаг из короткой записи */
 шаг(s,x,i){const {Ш,дом}=x;const П=[x.n.prof];const d=s.d||[60,300];
  switch(s.вид){
   case "принести":return Ш.принести(дом,П,s.что,s.т||`Принести: ${this.опись(s.что)}.`,s.дома?[s.дома]:[],s.подсказка?{подсказка:s.подсказка}:{});
   case "охота":return Ш.убить(s.n||3,s.fam||null,s.т,{x:дом.x,y:дом.y,r:s.r||250});
   case "засада":{const P=x.точка(дом,d[0],d[1],"z"+i,s.рельеф);x._P=P;return Object.assign(Ш.засада(P,s.где||"место",s.n||2,s.кто||"разбойник",`${s.т} (X ${P.x}, Y ${P.y}).`,s.слова||""),
    s.главарь?{главарь:s.главарь}:{},s.враг?{имяВрага:s.враг}:{},s.сильнее?{сильнее:s.сильнее}:{});}
   case "найти":{const P=x.точка(дом,d[0],d[1],"f"+i,s.рельеф);return Ш.найти(P,s.где||"место",s.вещь||"",`${s.т} (X ${P.x}, Y ${P.y}).`,s.слова||"",s.сырьё?{сырьё:true,k:s.k||1}:{});}
   case "починить":return Ш.починить(дом,s.инстр||[],s.мат||{},s.часов||2,s.т,s.слова||"Сделано.");
   case "заплатить":return Ш.заплатить(дом,П,s.n,s.т,s.дома?[s.дома]:[]);
   case "ждать":return Ш.ждать(s.часов||2,s.т,s.слова);}
  return null;},
 /* шаги дела по его виду */
 шаги(r,x){const {Ш,дом}=x;const П=[x.n.prof];const out=[];const вернуться=()=>Ш.говорить(дом,П,"Вернуться к заказчику.",[r.дома||"«Спасибо. Держи, как уговаривались»."]);
  const где=(V)=>`«${V.имя}» (X ${V.x}, Y ${V.y})`;const d=r.d||[100,500];
  switch(r.вид){
   case "принести":case "починить":case "заплатить":out.push(this.шаг(r,x,0));break;
   case "отнести":{const V=x.место(дом,d[0],d[1],"v");if(!V)return null;
    out.push(Ш.идти(V,`${r.т} — в ${где(V)}.`));
    out.push(Ш.принести(V,r.кому||["Старейшина","Фермер","Целительница"],r.груз,`Отдать в «${V.имя}»: ${this.опись(r.груз)}.`,[r.там||"«Дошло! Спасибо»."]));out.push(вернуться());break;}
   case "весть":{const V=x.место(дом,d[0],d[1],"v");if(!V)return null;
    out.push(Ш.идти(V,`${r.т} — в ${где(V)}.`));out.push(Ш.говорить(V,r.кому||["Старейшина"],`Поговорить в «${V.имя}».`,[r.там]));out.push(вернуться());break;}
   case "привезти":{const V=x.место(дом,d[0],d[1],"v");if(!V)return null;
    out.push(Ш.идти(V,`${r.т} — из ${где(V)}.`));out.push(Ш.говорить(V,r.кому||["Старейшина","Фермер"],`Забрать груз в «${V.имя}».`,[r.там],{дать:r.груз}));
    out.push(Ш.принести(дом,П,r.груз,`Довезти заказчику: ${this.опись(r.груз)}.`,[r.дома||"«Довёз! Вот спасибо»."]));break;}
   case "охота":out.push(this.шаг(r,x,0));out.push(вернуться());break;
   case "засада":out.push(this.шаг(r,x,0));
    if(r.добыча){const P=x._P;out.push(Ш.найти(P,r.где||"место",r.добыча.вещь,`Снять добычу: ${r.добыча.вещь}.`,r.добыча.слова||`Добыча ваша: ${r.добыча.вещь} ×${r.добыча.k||1}.`,{сырьё:true,k:r.добыча.k||1}));
     out.push(Ш.принести(дом,П,{[r.добыча.вещь]:r.добыча.k||1},`Отдать заказчику: ${r.добыча.вещь} ×${r.добыча.k||1}.`,[r.дома||"«Вот это добыча!»"]));}
    else out.push(вернуться());break;
   case "найти":out.push(this.шаг(r,x,0));if(r.сырьё)out.push(Ш.принести(дом,П,{[r.вещь]:r.k||1},`Отдать заказчику: ${r.вещь} ×${r.k||1}.`,[r.дома||"«Оно самое!»"]));else out.push(вернуться());break;
   case "сбор":out.push(Ш.дела(r.под.map((s,i)=>this.шаг(s,x,i+1)),r.т));out.push(вернуться());break;}
  if(!out.length||out.some(s=>!s))return null;
  if(r.выбор)out.splice(Math.max(0,out.length-1),0,Ш.выбор(r.выбор.вопрос,r.выбор.в));
  return out;},
 шаблон(r,гр){const шагов={принести:1,починить:1,заплатить:1,отнести:3,весть:3,привезти:3,охота:2,засада:r.добыча?3:2,найти:2,сбор:2}[r.вид]||2;
  return {id:"d_"+r.id,n:r.n,кат:r.кат||гр.кат,профы:r.профы||гр.профы,малое:true,шагов:шагов+(r.выбор?1:0),срок:r.срок,
   выдать:r.вид==="отнести"?r.груз:r.выдать,речь:()=>`«${r.речь}»`,
   шаги(x){return Дела170.шаги(r,x);},награда(x){return Дела170.награда(r,x);}};}};
